contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will try a Put (optionally with value) to ensure there is some balance, then attempt Collect.
    // Parameters:
    // putAmount: how much wei to send in Put (can be 0)
    // unlockTime: parameter to Put
    // collectAmount: amount to attempt to Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        // If we will send Ether to c for Put, ensure this contract has it
        if (putAmount > 0) {
            require(address(this).balance >= putAmount, "insufficient test balance for Put");
        }
        // Read balances before any calls
        uint beforeContractBal = address(c).balance;
        // read holder balance for this contract address
        (, uint beforeHolderBal) = c.Acc(address(this));

        // Perform Put to deposit funds and set unlock time
        if (putAmount > 0) {
            c.Put{value: putAmount}(unlockTime);
        } else {
            // still call Put with zero value to set unlock time if desired
            c.Put(unlockTime);
        }

        // Read after-put values
        uint afterPutContractBal = address(c).balance;
        (, uint afterPutHolderBal) = c.Acc(address(this));

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final values
        uint finalContractBal = address(c).balance;
        (, uint finalHolderBal) = c.Acc(address(this));

        // If Collect succeeded then holder balance and contract balance must have decreased by collectAmount.
        // If Collect reverted then balances must be unchanged from afterPut.
        assert(
            reverted
            ? (finalHolderBal == afterPutHolderBal && finalContractBal == afterPutContractBal)
            : (afterPutHolderBal >= collectAmount && finalHolderBal + collectAmount == afterPutHolderBal && finalContractBal + collectAmount == afterPutContractBal)
        );
    }

    // Allow receiving Ether so the test harness can fund this contract
    receive() external payable {}
}

