        // - If Collect succeeded then final balances are decreased by collectAmount from mid values.
        // Note: use non-underflowing comparisons by reasoning with >= where needed.
        assert(
            reverted
            ? (finalHolderBal == midHolderBal && finalContractBal == midContractBal)
            : (midHolderBal >= collectAmount && finalHolderBal + collectAmount == midHolderBal && finalContractBal + collectAmount == midContractBal)
