contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to Put some ether and then call Collect; assert that Collect never increases balances.
    // Parameters:
    // putAmount: amount sent to Put (may be 0)
    // unlockTime: parameter forwarded to Put
    // collectAmount: amount to attempt to Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        // Ensure this test contract can send putAmount when requested
        if (putAmount > 0) require(address(this).balance >= putAmount);

        // Observe holder record and contract balance before any interactions
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put (top-level call). Always call Put to possibly change holder state.
        c.Put{value: putAmount}(unlockTime);

        // Observe values immediately before Collect
        (uint midUnlock, uint midHolderBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Call Collect and detect revert
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after Collect
        (uint finalUnlock, uint finalHolderBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // General rule: Collect cannot increase the holder's recorded balance nor the contract's balance.
        // So finalHolderBal <= midHolderBal and finalContractBal <= midContractBal.
        // Additionally, Put can only have increased balances relative to before; ensure mid values are >= before when putAmount>0.
        // The assert must be a single general condition (not a constant) over observed values and params.
        assert(
            // Collect did not increase stored holder balance
            finalHolderBal <= midHolderBal
            // Collect did not increase contract ETH balance
            && finalContractBal <= midContractBal
            // sanity: after Put the holder and contract balances are at least as large as before when putAmount>0
            && (putAmount == 0 || (midHolderBal >= beforeHolderBal && midContractBal >= beforeContractBal))
        );
    }

    // allow receiving ether so harness can fund this contract
    receive() external payable {}
}

