contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We receive Ether so this test contract can forward funds to c
    receive() external payable {}

    // params: unlock time to pass to Put, amount of Ether to send
    function run(uint _unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read balance and holder info before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Call Put with provided amount, catch revert
        bool reverted;
        try c.Put{value: amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        /* Assert general rule:
           If Put did NOT revert then the stored balance for this holder must be >= beforeBalance
           and increased exactly by amount (no loss), and contract balance increased by at least amount.
           If Put reverted then balances must be unchanged.
        */
        assert(
            (!reverted && afterBalance == beforeBalance + amount && afterUnlock >= beforeUnlock && cBalAfter >= cBalBefore + amount)
            || (reverted && afterBalance == beforeBalance && afterUnlock == beforeUnlock && cBalAfter == cBalBefore)
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept funds so we can forward them to c in setup
    receive() external payable {}

    // params:
    // fundAmount - amount to deposit into c so that Collect might succeed
    // unlockDelta - seconds to set unlockTime in the future (if 0 uses block.timestamp)
    // collectAmt - amount to attempt to Collect
    function run(uint fundAmount, uint unlockDelta, uint collectAmt) public payable {
        // We need balance here to fund Put
        require(address(this).balance >= fundAmount);

        // Setup: deposit fundAmount into c so Acc[this] has funds and unlockTime set in future/present
        // call Put with unlock time = block.timestamp + unlockDelta (if overflow, it will revert; that's ok)
        bool putReverted;
        uint desiredUnlock = block.timestamp + unlockDelta;
        try c.Put{value: fundAmount}(desiredUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read holder before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Try Collect of collectAmt; Collect is payable in signature but uses _am param
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General rule asserted for all inputs:
        // - If Put previously reverted then nothing changed by Put, so beforeBalance==afterBalance and c balance unchanged.
        // - If Put succeeded and Collect succeeded then afterBalance == beforeBalance - collectAmt and cBalAfter <= cBalBefore - collectAmt
        //   (contract balance must decrease by at least collectAmt when Collect sends out funds).
        // - If Collect reverted then balances remain unchanged by Collect.
        // We combine into one assert covering all cases and avoid underflow in expressions by using comparisons.
        assert(
            (putReverted && afterBalance == beforeBalance && afterUnlock == beforeUnlock && cBalAfter == cBalBefore)
            || (!putReverted && !collectReverted && afterBalance + collectAmt == beforeBalance && cBalBefore >= cBalAfter + collectAmt)
            || (!putReverted && collectReverted && afterBalance == beforeBalance && afterUnlock == beforeUnlock && cBalAfter == cBalBefore)
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept funds so this contract can forward to c
    receive() external payable {}

    // params:
    // deposit - amount of wei to send to Put
    // unlockTime - value passed to Put
    function run(uint deposit, uint unlockTime) public payable {
        // require we have funds to forward
        require(address(this).balance >= deposit);

        // Record c balance and recorded holder balance before Put
        uint cBalBefore = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Call Put and catch revert
        bool putReverted;
        try c.Put{value: deposit}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after-state
        uint cBalAfter = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General rule:
        // - If Put reverted then nothing observable changed (c balance and Acc[this] unchanged).
        // - If Put succeeded then c balance increased by exactly deposit, and recorded balance did not decrease
        //   (afterBalance >= beforeBalance) and increased by at most deposit (afterBalance <= beforeBalance + deposit).
        assert(
            (putReverted && cBalAfter == cBalBefore && afterBalance == beforeBalance && afterUnlock == beforeUnlock)
            || (!putReverted && cBalAfter == cBalBefore + deposit && afterBalance >= beforeBalance && afterBalance <= beforeBalance + deposit)
        );
